const mockDelay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const DB = {
  async getProducts() {
    await mockDelay(300);
    return PRODUCTS;
  },
  async getProductById(id) {
    await mockDelay(100);
    return PRODUCTS.find(p => p.id === id);
  },
  async getCategories() {
    return CATEGORIES;
  }
};


